            RoomAckCarried, RoomAckDenied, RoomAckTabled, RoomAckSpreadsheet, RoomAckOrder, RoomCrewHeavy,
            RoomFactFestoon, RoomStrikeLookup, RoomTimeout, RoomClockZero, RoomCannedUnclear, RoomVerdictPerson,
            EarPractice, EarNotNow, EarNoSignal, EarScanFailed, EarHoldStill, EarHoldStill2,
            EarCannedUnclear, EarHintSmoker, EarHintFeed, EarHintWasps, EarHintHeat, EarHintWhatif,
            EarAsideWindow, EarAsideHornet,
        };

        static readonly GameLine[] LocalLines = { RoomFeedLiftHint };

        /// <summary>Every line: lines.json order, then the local-only ones. Allocates.</summary>
        public static GameLine[] All()
        {
            var all = new GameLine[FileLines.Length + LocalLines.Length];
            FileLines.CopyTo(all, 0);
            LocalLines.CopyTo(all, FileLines.Length);
            return all;
        }

        /// <summary>The ids that have (or should have) a clip in Resources/BeeswaxLines: every lines.json line, in file order. Allocates.</summary>
        public static string[] ClipIds()
        {
            var ids = new string[FileLines.Length];
            for (int i = 0; i < ids.Length; i++) ids[i] = FileLines[i].id;
            return ids;
        }

        /// <summary>A line the game plays that lines.json doesn't have (caption only).</summary>
        public static bool IsLocalOnly(string id)
        {
            for (int i = 0; i < LocalLines.Length; i++)
                if (LocalLines[i].id == id) return true;
            return false;
        }

        public static bool TryGet(string id, out GameLine line)
        {
            for (int i = 0; i < FileLines.Length; i++)
                if (FileLines[i].id == id) { line = FileLines[i]; return true; }
            for (int i = 0; i < LocalLines.Length; i++)
                if (LocalLines[i].id == id) { line = LocalLines[i]; return true; }
            line = default;
            return false;
        }

        public static bool TryGetOutcome(GameStation station, string choice, out GameOutcome outcome)
        {
            for (int i = 0; i < Outcomes.Length; i++)
            {
                if (Outcomes[i].station == station && Outcomes[i].choice == choice)
                {
                    outcome = Outcomes[i];
                    return true;
                }
            }
            outcome = default;
            return false;
        }

        /// <summary>Button label for a choice id.</summary>
        public static string Label(string choice)
        {
            switch (choice)
            {
                case GameIds.Choice.Swat: return "Swat";
                case GameIds.Choice.SprayWater: return "Spray water";
                case GameIds.Choice.Smoker: return "Smoker";
                case GameIds.Choice.StoreHoney: return "Store honey";
                case GameIds.Choice.SugarSyrup: return "Sugar syrup";
                case GameIds.Choice.BiggerDoor: return "Bigger door";
                case GameIds.Choice.SmallerDoor: return "Smaller door";
                case GameIds.Choice.DeepBowl: return "Deep bowl";
                case GameIds.Choice.PebbleDish: return "Pebble dish";
                case GameIds.Choice.Nothing: return "Nothing";
                default: return choice;
            }
        }
    }
}
